'use strict';
// Experimental route seam. Loaded only by the isolated React preview, never index.html/SW.
(()=>{let identity=null,sessionVersion=0;window.ATRY_SERVICES_PORT={
 agendaPreferences(patch){const keys={date:'dateAgenda',mode:'agendaMode',staff:'agendaStaff',resource:'agendaResource',status:'agendaStatusFilter',search:'agendaSearch',mobileDate:'agendaMobileDate',mobileStaff:'agendaMobileStaff',attention:'agendaAttention',toolsOpen:'agendaToolsOpen',filtersOpen:'agendaFiltersOpen',density:'agendaDensity',returnState:'agendaReturn'};if(patch)for(const [key,value]of Object.entries(patch))if(keys[key])state[keys[key]]=value;return {date:state.dateAgenda,mode:state.agendaMode||'dia',staff:state.agendaStaff||'',resource:state.agendaResource||'',status:state.agendaStatusFilter||'',search:state.agendaSearch||'',mobileDate:state.agendaMobileDate||'',mobileStaff:state.agendaMobileStaff||'',attention:Boolean(state.agendaAttention),toolsOpen:Boolean(state.agendaToolsOpen),filtersOpen:Boolean(state.agendaFiltersOpen),density:state.agendaDensity||'comfort',returnState:state.agendaReturn};},
 syncState:()=>({pending:Boolean(state.syncPending),connected:Boolean(state.syncConnected)}),
 session(){if(identity!==state.me){identity=state.me;sessionVersion++;}return state.me?.user?{userId:state.me.user.id,version:sessionVersion}:null;},
 scope(){this.session();return state.me?.user&&state.business?{sessionVersion,userId:state.me.user.id,businessId:state.business.id,role:state.business.role,sector:state.business.sector||'',accessEnabled:state.entitlements?.access_enabled===true}:null;},
 request:(route,options)=>api(route,options),
 publish(scope,catalog){const now=this.scope();if(!now||now.sessionVersion!==scope.sessionVersion||now.userId!==scope.userId||now.businessId!==scope.businessId||now.role!==scope.role||now.accessEnabled!==scope.accessEnabled)return;state.services=structuredClone(catalog.services);state.staffList=structuredClone(catalog.staff);},
 createHost(view='servicios',title='Servicios'){state.dialog=null;const marker=view==='servicios'?'data-react-services-root':view==='clientes'?'data-react-customers-root':'data-react-native-root';setScreen('<div data-react-view="'+esc(view)+'" '+marker+'></div>',title);return document.querySelector('[data-react-view]');},
 businesses:()=>structuredClone(state.businesses),
 accountTab(value){if(value!==undefined)state.accountTab=value;return state.accountTab||'perfil';},
 selectBusiness(id){disconnectAgendaEvents();if(!window.ATRY_DEMO?.enabled)localStorage.setItem('atry_biz',id);state.business=null;state.screen=null;state.staffList=[];state.currentBookings=[];state.agendaStaff='';nav('/app');},
 async organizationCreated(id){await refreshIdentity();if(!window.ATRY_DEMO?.enabled)localStorage.setItem('atry_biz',id);state.business=null;state.screen=null;nav('/app/configuracion-inicial');},
 endSession(){window.ATRY_SERVICES_EXTENSION?.signedOut();ATRY_APPEARANCE.apply(null);readCache.clear();disconnectAgendaEvents();state.me=null;state.business=null;state.businesses=[];nav('/login');},
 passwordChanged(){window.ATRY_SERVICES_EXTENSION?.signedOut();state.me=null;state.business=null;toast('Contraseña actualizada. Iniciá sesión nuevamente.');nav('/login');},
 user:()=>structuredClone(state.me.user),
 weeklyModel:(rows,end)=>agendaWeeklyModel(rows,end),
 dayTitle:day=>agendaDayTitle(day),
 openActivity(day){state.dateAgenda=day;state.agendaMobileDate=day;state.agendaMode='dia';state.agendaAttention=false;state.agendaSearch='';state.agendaStaff='';state.agendaResource='';state.agendaStatusFilter='';nav('/app/agenda');},
 resetAgendaToday(){state.dateAgenda=today();state.agendaMode='dia';state.agendaStaff='';state.agendaStatusFilter='';state.agendaSearch='';},
 notificationContext:()=>({planLabel:subscriptionPlan(state.business),mailProvider:state.config?.mail_provider||'',usage:structuredClone(state.entitlements.mail_usage||null)}),
 photoRequest:(route,body)=>photoRequest(route,body),
 photoBytes:image=>photoCore.bytes(image),
 publicURL:()=>businessUrl(),
 settingsTab(value){if(value!==undefined)state.settingsTab=value;return state.settingsTab||'general';},
 async applyBusiness(value){state.business={...state.business,...value};state.businesses=state.businesses.map(b=>b.id===state.business.id?{...b,...value}:b);state.screen=null;window.ATRY_SERVICES_EXTENSION?.beforePage();await renderApp();},
 async refreshPermissions(){await refreshIdentity();state.business=null;await renderApp();},
 completedOnboarding(){state.business=null;nav('/app/inicio');},
 privateEmployeeCatalog:()=>Boolean(window.ATRY_CLOUD),
 demo:()=>Boolean(window.ATRY_DEMO?.enabled),
 business:()=>structuredClone(state.business),
 capability:name=>hasCapability(name),
 dateAgenda:()=>state.dateAgenda,
 goAgenda(date){state.dateAgenda=date;nav('/app/agenda');},
 navigate:route=>nav(route),
 publishCustomers(rows){state.customers=structuredClone(rows);},
 whatsapp:()=>waCore,
 bookingIssues:(...args)=>agendaBookingIssues(...args),
 exactContacts:(...args)=>agendaExactContacts(...args),
 contactKey:(...args)=>agendaContactKey(...args),
 icon:name=>iconPaths[name]||iconPaths.info,
 serviceIcon:(sector,name)=>sectorIcon(sector,name),
 notify:(message,error)=>toast(message,error)
};})();
